#include<stdlib.h>
#include<string.h>
int Flatland[201][201];
int n,j,profundidad;
int max(int,int);
int fun(int,int);
int main(int argc, char *argv[]){
   int u,v;
   scanf("%d",&n);
       int i,j;
       for(i=1;i<n;i++){
           scanf("%d%d",&u,&v);
           Flatland[u][v]=1;
           Flatland[v][u]=1;
       }
        int beneficio=0;
        for(i=1; i<=n; i++){
            for(j=i+1;j<=n;j++){
                if(Flatland[i][j]==1){
                    int a=fun(i,j);
                    int b=fun(j,i);
                    beneficio=max(beneficio,a*b);
                }
            }
        }
        printf("%d\n",beneficio);
return 0;
}

int fun(int u,int hasta){
    int i,s=0;
    int distancia1=0,distancia2=0;
    for(i=1;i<=n;i++)
    if(Flatland[u][i]==1 && i!=hasta){
       s=max(fun(i,u),s);
      if(profundidad>distancia1){
          distancia2=distancia1;
          distancia1=profundidad;
      }
    }
    s=max(s,distancia1+distancia2);
    profundidad=distancia1+1;
    return s;
}

int max(int n1,int n2){
    int aux;
    if(n1<=n2){
        aux=n2;
    }else{
        aux=n1;
    }
    return aux;
}

